// Largest number of equal values (sort, then measure runs).
long long maxFrequency(vector<long long> v) {
    sort(v.begin(), v.end());
    long long best = 0;
    for (size_t i = 0, j; i < v.size(); i = j) {
        for (j = i; j < v.size() && v[j] == v[i]; j++) {}
        best = max<long long>(best, j - i);
    }
    return best;
}

