import java.util.Arrays;

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    // Largest number of equal values (sort, then measure runs).
    static int maxFrequency(long[] v) {
        Arrays.sort(v);
        int best = 0;
        for (int i = 0, j; i < v.length; i = j) {
            for (j = i; j < v.length && v[j] == v[i]; j++) {}
            best = Math.max(best, j - i);
        }
        return best;
    }

