package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

// maxFrequency returns the largest number of equal values.
func maxFrequency(v []int64) int {
	count := map[int64]int{}
	best := 0
	for _, x := range v {
		count[x]++
		best = max(best, count[x])
	}
	return best
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	x, y := make([]int64, n), make([]int64, n)
	for i := range x {
		x[i] = num()
	}
	for i := range y {
		y[i] = num()
	}
	// A vertical line fixes x, a horizontal line fixes y.
	best := max(maxFrequency(x), maxFrequency(y))
	if best < 2 {
		best = 0
	}
	fmt.Println(best)
}
